{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "ExtractionOutput",
  "description": "Structured fields extracted from a raw support ticket. Output of the extraction LLM, input to the scoring LLM.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "ticket_id",
    "language",
    "intent",
    "product_area",
    "sentiment",
    "entities",
    "summary_de",
    "summary_en"
  ],
  "properties": {
    "ticket_id": {
      "type": "string",
      "description": "Pass-through identifier from the webhook payload. Not generated by the LLM."
    },
    "language": {
      "type": "string",
      "enum": ["de", "en", "other"],
      "description": "Dominant language of the ticket body."
    },
    "intent": {
      "type": "string",
      "enum": [
        "breakdown_emergency",
        "repair_request",
        "appointment_scheduling",
        "appointment_confirmation",
        "billing_question",
        "warranty_claim",
        "quote_request",
        "complaint",
        "other"
      ],
      "description": "Primary intent. If multiple, pick highest-stakes."
    },
    "product_area": {
      "type": "string",
      "enum": ["heating_system", "heat_pump", "service_contract", "billing", "unknown"],
      "description": "Which product or service area the ticket concerns."
    },
    "sentiment": {
      "type": "string",
      "enum": ["negative", "neutral", "positive"],
      "description": "Overall emotional tone of the ticket sender."
    },
    "entities": {
      "type": "object",
      "additionalProperties": false,
      "required": ["addresses", "phone_numbers", "order_ids", "error_codes"],
      "properties": {
        "addresses": {"type": "array", "items": {"type": "string"}},
        "phone_numbers": {"type": "array", "items": {"type": "string"}},
        "order_ids": {"type": "array", "items": {"type": "string"}},
        "error_codes": {"type": "array", "items": {"type": "string"}}
      }
    },
    "summary_de": {
      "type": "string",
      "maxLength": 200,
      "description": "Two-sentence summary in German."
    },
    "summary_en": {
      "type": "string",
      "maxLength": 200,
      "description": "Two-sentence summary in English."
    }
  }
}

parameters.jsCode:
// Tier multiplier: deterministic priority calculation
// Inputs: scoring output (current node input) + original webhook payload
// Output: combined record ready for storage

const severityScale = {
  low: 1,
  medium: 2,
  high: 4,
  critical: 8
};

const tierWeights = {
  A: 1.5,
  B: 1.0,
  C: 0.7
};

// Heating-season window per German tenancy case law: Oct 1 – Apr 30
function isHeatingSeason(isoDate) {
  const md = isoDate.slice(5, 10); // "MM-DD"
  return md >= "10-01" || md <= "04-30";
}

// Pull scoring output — dig through the Responses API wrapper
const raw = $input.item.json;
const scoring = raw.output[0].content[0].text;

// Pull original webhook payload
const webhook = $('Webhook').item.json.body;

const severityScore = severityScale[scoring.severity];
const tierWeight = tierWeights[webhook.customer_tier];

if (severityScore === undefined) {
  throw new Error(`Unknown severity value: ${scoring.severity}`);
}
if (tierWeight === undefined) {
  throw new Error(`Unknown customer_tier value: ${webhook.customer_tier}`);
}

// Season multiplier: 1.0 in heating season, 0.7 outside
const inSeason = isHeatingSeason(webhook.received_at);
const seasonMultiplier = inSeason ? 1.0 : 0.7;

// Final priority = severity × tier × season
const finalPriority = severityScore * tierWeight * seasonMultiplier;

// Routing state: smallest viable safety rule (full routing tiers are v3, ADR-004).
// Safety signals already map to `critical` upstream in the scoring prompt; we
// re-check keywords here so the safety-critical path is enforced in code, not
// left to the LLM. Everything else is auto_accepted.
const SAFETY_PATTERN = /gas|gasgeruch|rauch|smoke|brand|burning|verbrann|funken/i;
const safetySignal =
  SAFETY_PATTERN.test(scoring.severity_reasoning || '') ||
  SAFETY_PATTERN.test(webhook.subject || '');
const routingState =
  (scoring.severity === 'critical' || safetySignal)
    ? 'human_review_mandatory'
    : 'auto_accepted';

return {
  json: {
    ticket_id: scoring.ticket_id,
    received_at: webhook.received_at,
    customer_id: webhook.customer_id,
    customer_type: webhook.customer_type,
    customer_tier: webhook.customer_tier,
    sender_email: webhook.sender_email,
    subject: webhook.subject,
    severity: scoring.severity,
    severity_score: severityScore,
    tier_weight: tierWeight,
    in_heating_season: inSeason,
    season_multiplier: seasonMultiplier,
    final_priority: finalPriority,
    routing_state: routingState,
    confidence: scoring.confidence,
    severity_reasoning: scoring.severity_reasoning,
    processed_at: new Date().toISOString()
  }
};

textOptions.schema:
{
  "title": "ScoringOutput",
  "description": "Severity assessment for a triaged ticket. Output of the scoring LLM.",
  "type": "object",
  "additionalProperties": false,
  "required": ["ticket_id", "severity", "severity_reasoning", "confidence"],
  "properties": {
    "ticket_id": {
      "type": "string",
      "description": "Pass-through identifier from the extraction step."
    },
    "severity": {
      "type": "string",
      "enum": ["low", "medium", "high", "critical"],
      "description": "Ordered severity level. critical > high > medium > low. When uncertain between adjacent levels, pick the higher."
    },
    "severity_reasoning": {
      "type": "string",
      "maxLength": 200,
      "description": "One short sentence in German explaining the primary reason for the severity assignment."
    },
    "confidence": {
      "type": "number",
      "minimum": 0,
      "maximum": 1,
      "description": "Relative confidence signal for ranking. NOT a calibrated probability."
    }
  }
}

parameters.jsCode:
const payload = $json.body ?? {};
const errors = [];

function isMissing(value) {
  return value === undefined || value === null || String(value).trim() === '';
}

// Required fields per webhook_input.schema.json
if (isMissing(payload.ticket_id)) errors.push('missing_ticket_id');
if (isMissing(payload.subject)) errors.push('missing_subject');
if (isMissing(payload.body)) errors.push('missing_body');
if (isMissing(payload.customer_type)) errors.push('missing_customer_type');
if (isMissing(payload.customer_tier)) errors.push('missing_customer_tier');
if (isMissing(payload.received_at)) errors.push('missing_received_at');
if (isMissing(payload.channel)) errors.push('missing_channel');

// Enum validations
const allowedCustomerTypes = ['private', 'business'];
if (!isMissing(payload.customer_type) && !allowedCustomerTypes.includes(payload.customer_type)) {
  errors.push('invalid_customer_type');
}

const allowedCustomerTiers = ['A', 'B', 'C'];
if (!isMissing(payload.customer_tier) && !allowedCustomerTiers.includes(payload.customer_tier)) {
  errors.push('invalid_customer_tier');
}

const allowedChannels = ['email', 'webform', 'phone_transcript', 'chat'];
if (!isMissing(payload.channel) && !allowedChannels.includes(payload.channel)) {
  errors.push('invalid_channel');
}

// Format validations
if (!isMissing(payload.received_at) && Number.isNaN(Date.parse(payload.received_at))) {
  errors.push('invalid_received_at');
}

return [
  {
    json: {
      valid: errors.length === 0,
      validation_errors: errors,
      payload
    }
  }
];

const input = $json;

let candidate =
  input.output?.[0]?.content?.[0]?.text ??
  input.output?.[0]?.text ??
  input.content?.[0]?.text ??
  input.text ??
  input.response ??
  input.output ??
  input.data ??
  input;

let parsed = null;
const errors = [];

try {
  if (typeof candidate === 'object' && candidate !== null && !Array.isArray(candidate)) {
    parsed = candidate;
  } else {
    let text = String(candidate).trim();
    text = text
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/i, '');
    parsed = JSON.parse(text);
  }
} catch (e) {
  errors.push('invalid_json');
}

const requiredFields = [
  'ticket_id',
  'language',
  'intent',
  'product_area',
  'sentiment',
  'entities',
  'summary_de',
  'summary_en'
];

if (parsed) {
  for (const field of requiredFields) {
    if (
      parsed[field] === undefined ||
      parsed[field] === null ||
      (typeof parsed[field] === 'string' && parsed[field].trim() === '')
    ) {
      errors.push(`missing_or_empty_${field}`);
    }
  }

  const allowedLanguage = ['de', 'en', 'other'];
  if (parsed.language && !allowedLanguage.includes(parsed.language)) {
    errors.push('invalid_language');
  }

  const allowedIntent = [
    'breakdown_emergency',
    'repair_request',
    'appointment_scheduling',
    'appointment_confirmation',
    'billing_question',
    'warranty_claim',
    'quote_request',
    'complaint',
    'other'
  ];
  if (parsed.intent && !allowedIntent.includes(parsed.intent)) {
    errors.push('invalid_intent');
  }

  const allowedProductArea = [
    'heating_system',
    'heat_pump',
    'service_contract',
    'billing',
    'unknown'
  ];
  if (parsed.product_area && !allowedProductArea.includes(parsed.product_area)) {
    errors.push('invalid_product_area');
  }

  const allowedSentiment = ['negative', 'neutral', 'positive'];
  if (parsed.sentiment && !allowedSentiment.includes(parsed.sentiment)) {
    errors.push('invalid_sentiment');
  }

  if (parsed.entities !== undefined) {
    if (typeof parsed.entities !== 'object' || parsed.entities === null || Array.isArray(parsed.entities)) {
      errors.push('invalid_entities_object');
    } else {
      for (const field of ['addresses', 'phone_numbers', 'order_ids', 'error_codes']) {
        if (!Array.isArray(parsed.entities[field])) {
          errors.push(`invalid_entities_${field}`);
        }
      }
    }
  }

  if (parsed.summary_de && parsed.summary_de.length > 200) {
    errors.push('summary_de_too_long');
  }

  if (parsed.summary_en && parsed.summary_en.length > 200) {
    errors.push('summary_en_too_long');
  }
}

return [
  {
    json: {
      valid: errors.length === 0,
      validation_errors: errors,
      extracted: parsed,
      raw_extractor_output: candidate
    }
  }
];

// Assemble a clean, complete payload for the scoring LLM.
// Drops the validation wrapper and raw_extractor_output; adds the business-
// context fields the scoring rules depend on, a computed season flag, and a
// bounded excerpt of the original ticket body so safety/vulnerability signals
// survive the summary compression.

const extracted = $json.extracted ?? {};
const webhook = $('Webhook').item.json.body ?? {};

// Heating season per German tenancy case law: Oct 1 – Apr 30
function isHeatingSeason(isoDate) {
  if (!isoDate) return null;
  const md = String(isoDate).slice(5, 10); // "MM-DD"
  return md >= "10-01" || md <= "04-30";
}

const ticketExcerpt = '<ticket>' + String(webhook.body ?? '').slice(0, 1500) + '</ticket>';

return {
  json: {
    ...extracted,
    customer_type: webhook.customer_type,
    customer_tier: webhook.customer_tier,
    property_count: webhook.property_count,
    building_type: webhook.building_type,
    occupant_flags: webhook.occupant_flags,
    received_at: webhook.received_at,
    in_heating_season: isHeatingSeason(webhook.received_at),
    ticket_excerpt: ticketExcerpt
  }
};

// Re-source the triage record from Normalize Final Record: the upstream HTTP
// Request (audit POST) replaced the active item with its response, so $json
// here is the audit response, not the record. Read the record explicitly so
// customData and the downstream Sheets append get the real fields.
const rec = $('Normalize Final Record').first().json;
$execution.customData.set('ticket_id', rec.ticket_id);
$execution.customData.set('final_priority', rec.final_priority);
$execution.customData.set('workflow_version', 'v2');
return [{ json: rec }];

$execution.customData.setAll({
  workflow_version: 'v2',
  ticket_id: $json.ticket_id,
  customer_id: $json.customer_id,
  final_priority: $json.final_priority,
  severity: $json.severity
});

return $input.all();
